mapper.select:
SELECT NULL AS stat_id, DATE(wo.actual_start) AS stat_date, COUNT(*) AS work_order_count, SUM(CASE WHEN wo.actual_finish IS NOT NULL THEN 1 ELSE 0 END) AS completed_count, SUM(CASE WHEN wo.actual_start IS NOT NULL AND wo.actual_finish IS NULL THEN 1 ELSE 0 END) AS in_progress_count, SUM(CASE WHEN COALESCE(wo.defect_qty, 0) > 0 THEN 1 ELSE 0 END) AS abnormal_count, COALESCE(SUM(wo.plan_qty), 0) AS total_plan_qty, COALESCE(SUM(wo.qualified_qty), 0) AS total_good_qty, COALESCE(SUM(wo.defect_qty), 0) AS total_defect_qty, 0 AS avg_oee, COALESCE(SUM(rpt_sum.report_count), 0) AS report_count, NULL AS create_time FROM mms_work_order wo LEFT JOIN ( SELECT r.work_order_id, COUNT(*) AS report_count FROM mms_work_report r WHERE r.del_flag = '0' GROUP BY r.work_order_id ) rpt_sum ON rpt_sum.work_order_id = wo.work_order_id
wo.del_flag = '0' AND wo.actual_start IS NOT NULL AND DATE(wo.actual_start) >= #{params.beginTime} AND DATE(wo.actual_start) <= #{params.endTime}
GROUP BY DATE(wo.actual_start) ORDER BY DATE(wo.actual_start) DESC
